   243  /**
   244   * xmlFuzzReadString:
   245   * @size:  size of string in bytes
   246   *
   247   * Read a random-length string from the fuzz data.
   248   *
   249   * The format is similar to libFuzzer's FuzzedDataProvider but treats
   250   * backslash followed by newline as end of string. This makes the fuzz data
   251   * more readable. A backslash character is escaped with another backslash.
   252   *
   253   * Returns a zero-terminated string or NULL if the fuzz data is exhausted.
   254   */
   255  const char *
   256  xmlFuzzReadString(size_t *size) {
   257      const char *out = fuzzData.outPtr;
   258
   259      while (fuzzData.remaining > 0) {
   260          int c = *fuzzData.ptr++;
   261          fuzzData.remaining--;
   262
   263          if ((c == '\\') && (fuzzData.remaining > 0)) {
   264              int c2 = *fuzzData.ptr;
   265
   266              if (c2 == '\n') {
   267                  fuzzData.ptr++;
   268                  fuzzData.remaining--;
   269                  if (size != NULL)
   270                      *size = fuzzData.outPtr - out;
   271                  *fuzzData.outPtr++ = '\0';
   272                  return(out);
   273              }
   274              if (c2 == '\\') {
   275                  fuzzData.ptr++;
   276                  fuzzData.remaining--;
   277              }
   278          }
   279
   280          *fuzzData.outPtr++ = c;
   281      }
   282
   283      if (fuzzData.outPtr > out) {
   284          if (size != NULL)
   285              *size = fuzzData.outPtr - out;
   286          *fuzzData.outPtr++ = '\0';
   287          return(out);
   288      }
   289
   290      if (size != NULL)
   291          *size = 0;
   292      return(NULL);
   293  }
